+  const hash = (token: string) => createHash("sha256").update(token).digest("hex");
+  const matches = (actual: string, expected: string) => {
+    const actualBytes = Buffer.from(actual);
+    const expectedBytes = Buffer.from(expected);
+    return actualBytes.length === expectedBytes.length && timingSafeEqual(actualBytes, expectedBytes);
+  };
+  const authorize = async (access: ParticipantAccessInput) => {
+    const run = access.testRunId ? await input.repository.getTestRunById(access.testRunId) : null;
+    if (access.testRunId && !run) throw input.invalidAccess();
+    const participantSessionId = access.participantSessionId?.trim() || run?.participantSessionId;
+    if (!participantSessionId || (run && run.participantSessionId !== participantSessionId)) {
+      throw input.invalidAccess();
+    }
+    const credential = await input.repository.getParticipantAccessCredential(participantSessionId);
+    const token = access.sessionToken;
