+const context = {
+  URL,
+  self: {
+    location: { origin: "https://testcenter.example" },
+    registration: { scope: "https://testcenter.example/app/" },
+    addEventListener() {}
+  }
+};
+runInNewContext(`${source}\nglobalThis.testDrain = drainParticipantBackgroundSaves;`, context);
