+import assert from "node:assert/strict";
+import test from "node:test";
+import { readFile } from "node:fs/promises";
+import ts from "typescript";
+
+// Execute the actual entry method, without bootstrapping Angular, HTTP or the
+// complete facade. Only its presentation/persistence collaborators are stubbed.
+const source = await readFile(new URL("../apps/web/src/app/participant-view.facade.ts", import.meta.url), "utf8");
+const ast = ts.createSourceFile("participant-view.facade.ts", source, ts.ScriptTarget.Latest, true);
+const facade = ast.statements.find(node => ts.isClassDeclaration(node) && node.name?.text === "ParticipantViewFacade");
+const method = facade?.members.find(node => ts.isMethodDeclaration(node) && node.name.getText(ast) === "applyEntryParameters");
+assert.ok(method, "The actual participant entry method must be present.");
+const compiled = ts.transpileModule(`export class EntryView { ${method.getText(ast)} }`, {
+  compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.ES2022 }
+}).outputText;
+const { EntryView } = await import(`data:text/javascript;base64,${Buffer.from(compiled).toString("base64")}`);
+
+const target = { tenantKey: "tenant", workspaceKey: "workspace", loginKey: "new-login", groupKey: "new-group", bookletKey: "booklet" };
+const fixture = () => Object.assign(new EntryView(), {
+  workspace: { tenantKey: target.tenantKey, workspaceKey: target.workspaceKey },
+  runtime: { ...target, participantSessionId: "old-session", testRunId: "old-run", currentRunStateView: "old cached state", currentUnitResponse: "saved opaque answer" },
+  currentRunState: { participantSession: { participantSessionId: "old-session", loginKey: "old-login" } },
+  syncParticipantHeaderVisibility() {}, persistState() {}
+});
+
+test("a new-login link cannot reuse a stale session after operator fields were already preselected", () => {
+  const view = fixture();
+  view.applyEntryParameters(target);
+  assert.equal(view.runtime.participantSessionId, "");
+  assert.equal(view.runtime.testRunId, "");
+  assert.equal(view.currentRunState, null);
+  assert.equal(view.runtime.loginKey, target.loginKey);
+});
+test("an explicit login without a workspace parameter also owns login selection", () => {
+  const view = fixture();
+  view.applyEntryParameters({ loginKey: target.loginKey });
+  assert.equal(view.runtime.participantSessionId, "");
+  assert.equal(view.runtime.testRunId, "");
+});
+test("an explicit authorized session link keeps its exact selected run", () => {
+  const view = fixture();
+  view.applyEntryParameters({ ...target, participantSessionId: "linked-session", testRunId: "linked-run" });
+  assert.equal(view.runtime.participantSessionId, "linked-session");
+  assert.equal(view.runtime.testRunId, "linked-run");
+});
+test("historical session-only links clear stale run selection without starting a new login", () => {
+  const view = fixture();
+  view.applyEntryParameters({ participantSessionId: "linked-session" });
+  assert.equal(view.runtime.participantSessionId, "linked-session");
+  assert.equal(view.runtime.testRunId, "");
+});
+test("an unparameterized participant page preserves its existing selection and answer", () => {
+  const view = fixture();
+  const previous = view.currentRunState;
+  view.applyEntryParameters({});
+  assert.equal(view.runtime.participantSessionId, "old-session");
+  assert.equal(view.runtime.testRunId, "old-run");
+  assert.equal(view.currentRunState, previous);
+  assert.equal(view.runtime.currentUnitResponse, "saved opaque answer");
+});
